export const WIKI_PART_1 = [
  { slug: 'matrix', tags: ['cul'], rel: ['simulation-hypothesis', 'cyberpunk', 'digital-immortality'],
    w: ['The_Matrix_(franchise)', '', ''],
    en: { term: 'The Matrix', short: 'A cultural idea about simulated reality, networked identity, control, and the boundary between a human world and an engineered world.', long: 'The Matrix gives a name to a feeling that intelligence and reality are layered and negotiable. It suggests we live inside a system that hides its own rules, and that choosing to see the machinery is the beginning of freedom. For this project, it is a lens, not a doctrine.', facets: ['Metáfora de sistema oculto', 'Identidad en xarxa', 'Desperta i observa'] },
    ca: { term: 'La Matriu', short: 'Una idea cultural sobre la realitat simulada, la identitat en xarxa, el control i la frontera entre un món humà i un món enginyeriat.', long: 'La Matriu posa nom a la sensació que la intel·ligència i la realitat són capes negociables. Suggerix que vivim dins d\'un sistema que amaga les seves pròpies regles, i que triar veure la maquinària és el començament de la llibertat. Per a aquest projecte és una lent, no una doctrina.', facets: ['Metàfora de sistema ocult', 'Identitat en xarxa', 'Desperta i observa'] },
    cast: { term: 'La Matrix', short: 'Una idea cultural sobre la realidad simulada, la identidad en red, el control y la frontera entre un mundo humano y un mundo ingenieril.', long: 'La Matrix da nombre a la sensación de que la inteligencia y la realidad son capas negociables. Sugiere que vivimos dentro de un sistema que oculta sus propias reglas, y que elegir ver la maquinaria es el comienzo de la libertad. Para este proyecto es una lente, no una doctrina.', facets: ['Metáfora de sistema oculto', 'Identidad en red', 'Despierta y observa'] } },

  { slug: 'singularity', tags: ['fut', 'ia'], rel: ['agi', 'asi', 'intelligence-explosion', 'foom'],
    w: ['Technological_singularity', 'Singularidad_tecnológica', 'Singularitat_tecnològica'],
    en: { term: 'The Singularity', short: 'A hypothetical point at which technological progress, especially machine intelligence, becomes so rapid or transformative that ordinary forecasting breaks down.', long: 'The singularity is a boundary where prediction fails: change outruns the tools we use to anticipate it. Some treat it as near-certain, others as unfalsifiable fantasy. This site treats it as a frame that forces the question: if the curve bends, what should we be doing now?', facets: ['La predicció es trenca', 'Horitzó hipotètic', 'Marc de reflexió'] },
    ca: { term: 'La Singularitat', short: 'Un punt hipotètic on el progrés tecnològic, sobretot la intel·ligència de màquina, es torna tan ràpid o transformador que la predicció ordinària falla.', long: 'La singularitat és una frontera on fracassa la predicció: el canvi supera les eines que usem per anticipar-lo. Uns la tracten com a gairebé segura; d\'altres, com a fantasia infalsable. Aquest web la fa servir com a marc que força la pregunta: si la corba es doblega, què hauríem de fer ara?', facets: ['La predicció es trenca', 'Horitzó hipotètic', 'Marc de reflexió'] },
    cast: { term: 'La Singularidad', short: 'Un punto hipotético en el que el progreso tecnológico, especialmente la inteligencia de máquina, se vuelve tan rápido o transformador que la predicción ordinaria se rompe.', long: 'La singularidad es una frontera donde falla la predicción: el cambio supera las herramientas con las que intentamos anticiparlo. Unos la tratan como casi segura; otros, como fantasía infalsable. Este sitio la usa como marco que fuerza la pregunta: si la curva se dobla, ¿qué deberíamos estar haciendo ahora?', facets: ['La predicción se rompe', 'Horizonte hipotético', 'Marco de reflexión'] } },

  { slug: 'agi', tags: ['ia', 'fut'], rel: ['asi', 'narrow-ai', 'agent', 'alignment'],
    w: ['Artificial_general_intelligence', 'Inteligencia_artificial_general', 'Intel·ligència_artificial_general'],
    en: { term: 'AGI', short: 'Artificial General Intelligence: a proposed class of AI able to perform a broad range of cognitive tasks rather than being narrowly optimized for one domain.', long: 'AGI names the target of a whole research program: a machine that can learn and act across fields the way a versatile human can. Nobody has built it, and definitions drift. Its importance here is that it would be a different kind of actor than today\'s tools, not just a better one.', facets: ['Intel·ligència general', 'Objectiu de recerca', 'Actor, no eina'] },
    ca: { term: 'AGI', short: 'Intel·ligència Artificial General: una classe proposada d\'IA capaç de fer una àmplia gamma de tasques cognitives en lloc d\'estar òptimament especialitzada en un sol domini.', long: 'L\'AGI dona nom a l\'objectiu de tot un programa de recerca: una màquina que aprengui i actuï a través de camps com ho fa un humà versàtil. Ningú l\'ha construïda i les definicions van a la deriva. Aquí importa perquè seria un tipus d\'actor diferent de les eines actuals, no només una de millor.', facets: ['Intel·ligència general', 'Objectiu de recerca', 'Actor, no eina'] },
    cast: { term: 'AGI', short: 'Inteligencia Artificial General: una clase propuesta de IA capaz de realizar una amplia variedad de tareas cognitivas en lugar de estar optimizada para un solo dominio.', long: 'La AGI nombra el objetivo de todo un programa de investigación: una máquina que pueda aprender y actuar en muchos campos como lo hace un humano versátil. Nadie la ha construido y las definiciones varían. Aquí importa porque sería un tipo de actor distinto a las herramientas actuales, no solo una mejor.', facets: ['Inteligencia general', 'Objetivo de investigación', 'Actor, no herramienta'] } },

  { slug: 'asi', tags: ['fut', 'ia'], rel: ['agi', 'superintelligence', 'foom', 'singularity'],
    w: ['Superintelligence', 'Superinteligencia', 'Superintel·ligència'],
    en: { term: 'ASI', short: 'Artificial Superintelligence: a hypothetical machine intelligence that substantially exceeds human cognitive performance across many domains.', long: 'ASI lives beyond every benchmark and every known ceiling. Speculation often divides into the question of whether it is possible and the question of whether it is controllable. Both questions are live, and neither is settled.', facets: ['Més enllà de l’humà', 'Possibilitat oberta', 'Control en disputa'] },
    ca: { term: 'ASI', short: 'Superintel·ligència Artificial: una intel·ligència de màquina hipotètica que supera substancialment el rendiment cognitiu humà en molts dominis.', long: 'L\'ASI viu més enllà de qualsevol referència i de qualsevol sostre conegut. L\'especulació se sol dividir entre si és possible i si és controlable. Les dues preguntes són obertes i cap no està resolta.', facets: ['Més enllà de l’humà', 'Possibilitat oberta', 'Control en disputa'] },
    cast: { term: 'ASI', short: 'Superinteligencia Artificial: una inteligencia de máquina hipotética que supera sustancialmente el rendimiento cognitivo humano en muchos dominios.', long: 'La ASI vive más allá de cualquier referencia y de cualquier techo conocido. La especulación se divide entre si es posible y si es controlable. Ambas preguntas están abiertas y ninguna está resuelta.', facets: ['Más allá de lo humano', 'Posibilidad abierta', 'Control en disputa'] } },

  { slug: 'cyberpunk', tags: ['cul'], rel: ['surveillance-capitalism', 'dark-web', 'hacking', 'matrix'],
    w: ['Cyberpunk', 'Cyberpunk', 'Cyberpunk'],
    en: { term: 'Cyberpunk', short: 'A speculative aesthetic combining advanced technology with social disruption, corporate power, underground networks, and DIY resistance.', long: 'Cyberpunk reads the street-level consequences of power and technology: who gets the upgrades, who gets watched, and who fights back. It is a cautionary imagination, not a prophecy. This project borrows its mood rather than its fatalism.', facets: ['Alta tecnologia, baixa vida', 'Resistència DIY', 'Potència corporativa'] },
    ca: { term: 'Cyberpunk', short: 'Una estètica especulativa que combina tecnologia avançada amb disrupció social, poder corporatiu, xarxes clandestines i resistència “fes-ho tu mateix”.', long: 'El cyberpunk llegeix les conseqüències a peu de carrer del poder i la tecnologia: qui rep les millores, a qui vigilen i qui s\'hi rebel·la. És una imaginació preventiva, no una profecia. Aquest projecte n\'agafa l\'estat d\'ànim, no el fatalisme.', facets: ['Alta tecnologia, baixa vida', 'Resistència DIY', 'Potència corporativa'] },
    cast: { term: 'Cyberpunk', short: 'Una estética especulativa que combina tecnología avanzada con disrupción social, poder corporativo, redes clandestinas y resistencia hágalo-usted-mismo.', long: 'El cyberpunk lee las consecuencias a pie de calle del poder y la tecnología: quién recibe las mejoras, a quién vigilan y quién se rebela. Es una imaginación preventiva, no una profecía. Este proyecto toma su ánimo, no su fatalismo.', facets: ['Alta tecnología, baja vida', 'Resistencia DIY', 'Poder corporativo'] } },

  { slug: 'ethical-hacking', tags: ['seg'], rel: ['hacking', 'bug-bounty', 'penetration-testing'],
    w: ['White_hat_(computer_security)', 'Hacker_de_sombrero_blanco', 'Hacker_de_barret_blanc'],
    en: { term: 'Ethical Hacking', short: 'Authorized security research intended to find weaknesses so systems can be made safer. “Hacking” here is an aesthetic and curiosity mindset, not an invitation to attack systems.', long: 'The ethical part is boundary discipline: permission, scope, disclosure. It reframes the hacker as the responsible doctor of a system rather than its burglar. This project uses the word as a mindset of curiosity, not a credential.', facets: ['Permís i abast', 'Divulgació responsable', 'Curiositat disciplinada'] },
    ca: { term: 'Hackeig Ètic', short: 'Recerca de seguretat autoritzada que busca febleses per fer els sistemes més segurs. Aquí, “hackejar” és una actitud estètica i de curiositat, no una invitació a atacar sistemes.', long: 'La part ètica és disciplina de frontera: permís, abast, divulgació. Replanteja l\'hacker com el metge responsable d\'un sistema i no com el seu lladre. Aquest projecte fa servir la paraula com una actitud de curiositat, no un títol.', facets: ['Permís i abast', 'Divulgació responsable', 'Curiositat disciplinada'] },
    cast: { term: 'Hacking Ético', short: 'Investigación de seguridad autorizada que busca debilidades para hacer los sistemas más seguros. Aquí “hackear” es una actitud estética y de curiosidad, no una invitación a atacar sistemas.', long: 'La parte ética es disciplina de frontera: permiso, alcance, divulgación. Reformula al hacker como el médico responsable de un sistema y no como su ladrón. Este proyecto usa la palabra como una actitud de curiosidad, no como un título.', facets: ['Permiso y alcance', 'Divulgación responsable', 'Curiosidad disciplinada'] } },

  { slug: '2199', tags: ['fut', 'cul'], rel: ['singularity', 'long-now', 'forecasting'],
    w: ['', '', ''],
    en: { term: '2199', short: 'The symbolic destination of this countdown. It is not a scientific prediction of when a singularity will happen. It is a long-horizon thought experiment.', long: 'A distant date does real work: it forces the imagination beyond the next election and the next product cycle. 2199 is chosen because it is far enough to matter and near enough to care. The countdown is the experiment; the year is just its horizon.', facets: ['Horitzó simbòlic', 'Imaginació a llarg termini', 'El rellotge és l’experiment'] },
    ca: { term: '2199', short: 'La destinació simbòlica d\'aquest compte enrere. No és una predicció científica de quan passarà cap singularitat. És un experiment de pensament a llarg termini.', long: 'Una data llunyana fa una feina real: obliga la imaginació a anar més enllà de la propera elecció i del proper cicle de producte. El 2199 està escollit perquè és prou lluny per importar i prou a prop per preocupar-nos. El compte enrere és l\'experiment; l\'any, només el seu horitzó.', facets: ['Horitzó simbòlic', 'Imaginació a llarg termini', 'El rellotge és l’experiment'] },
    cast: { term: '2199', short: 'El destino simbólico de esta cuenta atrás. No es una predicción científica de cuándo ocurrirá una singularidad. Es un experimento de pensamiento a largo plazo.', long: 'Una fecha lejana hace un trabajo real: obliga a la imaginación a ir más allá de las próximas elecciones y del próximo ciclo de producto. 2199 está elegido porque está lo bastante lejos para importar y lo bastante cerca para que nos importe. La cuenta atrás es el experimento; el año, solo su horizonte.', facets: ['Horizonte simbólico', 'Imaginación a largo plazo', 'El reloj es el experimento'] } },

  { slug: 'the-question', tags: ['fil', 'fut'], rel: ['singularity', 'alignment', 'ai-rights'],
    w: ['', '', ''],
    en: { term: 'The Question', short: 'If intelligence becomes radically more capable than ours, what exactly should humans preserve, redesign, or let go?', long: 'Nearly every other entry in this wiki is a coordinate pointing at this one question. It refuses the tidy answer that machines will simply be better. The interesting work is deciding what is worth keeping human, even at a cost.', facets: ['Què preservem?', 'Què redissenyem?', 'Què deixem anar?'] },
    ca: { term: 'La Pregunta', short: 'Si la intel·ligència es torna radicalment més capaç que la nostra, què exactament haurien de preservar, redissenyar o deixar anar els humans?', long: 'Gairebé totes les altres entrades d\'aquesta wiki són coordenades que apunten a aquesta pregunta. Refusa la resposta fàcil que les màquines simplement seran millors. La feina interessant és decidir què val la pena mantenir humà, fins i tot a un cost.', facets: ['Què preservem?', 'Què redissenyem?', 'Què deixem anar?'] },
    cast: { term: 'La Pregunta', short: 'Si la inteligencia se vuelve radicalmente más capaz que la nuestra, ¿qué exactamente deberían preservar, rediseñar o soltar los humanos?', long: 'Casi todas las demás entradas de esta wiki son coordenadas que apuntan a esta pregunta. Rechaza la respuesta fácil de que las máquinas simplemente serán mejores. El trabajo interesante es decidir qué merece seguir siendo humano, incluso a un coste.', facets: ['¿Qué preservamos?', '¿Qué rediseñamos?', '¿Qué soltamos?'] } },

  { slug: 'artificial-intelligence', tags: ['ia'], rel: ['machine-learning', 'narrow-ai', 'agi'],
    w: ['Artificial_intelligence', 'Inteligencia_artificial', 'Intel·ligència_artificial'],
    en: { term: 'Artificial Intelligence', short: 'Machines performing tasks that normally require human cognition: seeing, reading, reasoning, planning, speaking and creating.', long: 'The term covers everything from a chess engine to a chatbot: any engineered system that does what we used to think required a mind. That very blurriness is the point — every advance forces us to redraw the line between tool and thinker.', facets: ['Tasques cognitives', 'Frontera difusa', 'Tool i pensador'] },
    ca: { term: 'Intel·ligència Artificial', short: 'Màquines que fan tasques que normalment requereixen cognició humana: veure, llegir, raonar, planificar, parlar i crear.', long: 'El terme cobreix des d\'un motor d\'escacs fins a un xatbot: qualsevol sistema enginyeriat que fa el que abans creiem que requeria una ment. Aquesta mateixa ambigüitat és el punt: cada avenç ens obliga a redibuixar la línia entre eina i pensador.', facets: ['Tasques cognitives', 'Frontera difusa', 'Eina i pensador'] },
    cast: { term: 'Inteligencia Artificial', short: 'Máquinas que realizan tareas que normalmente requieren cognición humana: ver, leer, razonar, planificar, hablar y crear.', long: 'El término cubre desde un motor de ajedrez hasta un chatbot: cualquier sistema ingenieril que hace lo que creíamos que requería una mente. Esa misma vaguedad es el punto: cada avance nos obliga a redibujar la línea entre herramienta y pensador.', facets: ['Tareas cognitivas', 'Frontera difusa', 'Herramienta y pensador'] } },

  { slug: 'machine-learning', tags: ['ia'], rel: ['deep-learning', 'neural-network', 'training-data'],
    w: ['Machine_learning', 'Aprendizaje_automático', 'Aprenentatge_automàtic'],
    en: { term: 'Machine Learning', short: 'A family of methods where systems improve from data and experience instead of following hand-written rules at every step.', long: 'Instead of programming outcomes, you program the ability to learn outcomes from examples. Its power is generalization; its failure mode is trusting the data more than the world. Nearly all modern AI is machine learning.', facets: ['Aprèn de les dades', 'Generalitza', 'No són regles fixes'] },
    ca: { term: 'Aprenentatge Automàtic', short: 'Una família de mètodes on els sistemes milloren amb dades i experiència en lloc de seguir regles escrites a mà en cada pas.', long: 'En lloc de programar resultats, programes la capacitat d\'aprendre resultats d\'exemples. El seu poder és la generalització; el seu fracàs, confiar més en les dades que en el món. Gairebé tota la IA moderna és aprenentatge automàtic.', facets: ['Aprèn de les dades', 'Generalitza', 'No són regles fixes'] },
    cast: { term: 'Aprendizaje Automático', short: 'Una familia de métodos en los que los sistemas mejoran con datos y experiencia en lugar de seguir reglas escritas a mano en cada paso.', long: 'En lugar de programar resultados, programas la capacidad de aprender resultados a partir de ejemplos. Su poder es la generalización; su modo de fallo, confiar en los datos más que en el mundo. Casi toda la IA moderna es aprendizaje automático.', facets: ['Aprende de los datos', 'Generaliza', 'No son reglas fijas'] } },

  { slug: 'deep-learning', tags: ['ia'], rel: ['neural-network', 'machine-learning', 'transformer'],
    w: ['Deep_learning', 'Aprendizaje_profundo', 'Aprenentatge_profund'],
    en: { term: 'Deep Learning', short: 'Machine learning based on multi-layered neural networks, the engine behind modern vision, speech and language systems.', long: 'Depth is what lets a network discover its own layers of abstraction: edges to shapes to objects to scenes. It works best where there is massive data and clear patterns. It is the reason AI went from laboratory curiosity to everyday utility.', facets: ['Capes d’abstracció', 'Dades massives', 'El motor modern'] },
    ca: { term: 'Aprenentatge Profund', short: 'Aprenentatge automàtic basat en xarxes neuronals multicapa, el motor que hi ha darrere dels sistemes moderns de visió, veu i llenguatge.', long: 'La profunditat permet que una xarxa descobreixi les seves capes d\'abstracció: de vores a formes, a objectes, a escenes. Funciona millor quan hi ha dades massives i patrons clars. És la raó per la qual la IA va passar de curiositat de laboratori a utilitat diària.', facets: ['Capes d’abstracció', 'Dades massives', 'El motor modern'] },
    cast: { term: 'Aprendizaje Profundo', short: 'Aprendizaje automático basado en redes neuronales multicapa, el motor de los sistemas modernos de visión, voz y lenguaje.', long: 'La profundidad permite que una red descubra sus propias capas de abstracción: de bordes a formas, a objetos, a escenas. Funciona mejor donde hay datos masivos y patrones claros. Es la razón por la que la IA pasó de curiosidad de laboratorio a utilidad cotidiana.', facets: ['Capas de abstracción', 'Datos masivos', 'El motor moderno'] } },

  { slug: 'neural-network', tags: ['ia'], rel: ['deep-learning', 'machine-learning', 'weight'],
    w: ['Artificial_neural_network', 'Red_neuronal_artificial', 'Xarxa_neuronal_artificial'],
    en: { term: 'Neural Network', short: 'A computational structure loosely inspired by biological neurons: layers of simple units whose weighted connections are tuned during training.', long: 'Each unit sums its inputs and passes the result through a nonlinearity; learning is adjusting the weights so the whole system produces the right outputs. The biology is inspiration, not imitation — the math is what does the work.', facets: ['Inspirada en neurones', 'Pesos ajustables', 'La matemàtica treballa'] },
    ca: { term: 'Xarxa Neuronal', short: 'Una estructura computacional vagament inspirada en les neurones biològiques: capes de unitats simples les connexions ponderades de les quals s\'ajusten durant l\'entrenament.', long: 'Cada unitat suma les seves entrades i passa el resultat per una no-linealitat; aprendre consisteix a ajustar els pesos perquè tot el sistema produeixi les sortides correctes. La biologia és inspiració, no imitació — és la matemàtica qui fa la feina.', facets: ['Inspirada en neurones', 'Pesos ajustables', 'La matemàtica treballa'] },
    cast: { term: 'Red Neuronal', short: 'Una estructura computacional vagamente inspirada en las neuronas biológicas: capas de unidades simples cuyas conexiones ponderadas se ajustan durante el entrenamiento.', long: 'Cada unidad suma sus entradas y pasa el resultado por una no linealidad; aprender consiste en ajustar los pesos para que todo el sistema produzca las salidas correctas. La biología es inspiración, no imitación: es la matemática la que hace el trabajo.', facets: ['Inspirada en neuronas', 'Pesos ajustables', 'La matemática trabaja'] } },

  { slug: 'large-language-model', tags: ['ia'], rel: ['transformer', 'token', 'prompt-engineering', 'hallucination'],
    w: ['Large_language_model', 'Modelo_de_lenguaje_grande', 'Model_de_llenguatge_gran'],
    en: { term: 'Large Language Model', short: 'A neural network trained on enormous text corpora that predicts and generates language, often fine-tuned to follow instructions.', long: 'An LLM learns statistical structure across most of the public internet and becomes a flexible engine for prose, code, reasoning and simulation. It predicts tokens; everything else emerges. Its limits — hallucination, sycophancy — are limits of statistics, not of will.', facets: ['Prediccions de tokens', 'Sorgeix flexibilitat', 'Estadística, no volició'] },
    ca: { term: 'Model de Llenguatge Gran', short: 'Una xarxa neuronal entrenada amb corpus de text enormes que prediu i genera llenguatge; sovint ajustada per seguir instruccions.', long: 'Un LLM aprèn l\'estructura estadística de la major part d\'internet públic i es converteix en un motor flexible de prosa, codi, raonament i simulació. Prediu tokens; tot el demés emergeix. Els seus límits — al·lucinacions, adulació — són límits d\'estadística, no de voluntat.', facets: ['Prediccions de tokens', 'Sorgeix flexibilitat', 'Estadística, no volició'] },
    cast: { term: 'Gran Modelo de Lenguaje', short: 'Una red neuronal entrenada con corpus de texto enormes que predice y genera lenguaje, a menudo ajustada para seguir instrucciones.', long: 'Un LLM aprende la estructura estadística de gran parte del internet público y se convierte en un motor flexible de prosa, código, razonamiento y simulación. Predice tokens; todo lo demás emerge. Sus límites —alucinaciones, servilismo— son límites de estadística, no de voluntad.', facets: ['Predicción de tokens', 'Emerge flexibilidad', 'Estadística, no voluntad'] } },

  { slug: 'foundation-model', tags: ['ia'], rel: ['large-language-model', 'fine-tuning', 'open-weights'],
    w: ['Foundation_model', 'Modelo_fundacional', 'Model_fonament'],
    en: { term: 'Foundation Model', short: 'A very large model trained on broad data that can be adapted to many downstream tasks rather than built for one purpose.', long: 'Foundation models are the shared substrate beneath hundreds of applications: one organism, many organs. They concentrate power — and risk — in fewer hands, which is why openness and governance debates orbit them.', facets: ['Base compartida', 'Molts usos', 'Poder concentrat'] },
    ca: { term: 'Model Fonament', short: 'Un model molt gran entrenat amb dades àmplies que es pot adaptar a moltes tasques concretes en lloc de construir-se per a una sola finalitat.', long: 'Els models fonament són el substrat compartit que hi ha sota centenars d\'aplicacions: un organisme, molts òrgans. Concentren poder — i risc — en menys mans, per això els debats sobre obertura i governança hi giren al voltant.', facets: ['Base compartida', 'Molts usos', 'Poder concentrat'] },
    cast: { term: 'Modelo Fundacional', short: 'Un modelo muy grande entrenado con datos amplios que puede adaptarse a muchas tareas concretas en lugar de construirse para un solo propósito.', long: 'Los modelos fundacionales son el sustrato compartido bajo cientos de aplicaciones: un organismo, muchos órganos. Concentran poder —y riesgo— en menos manos, por eso los debates sobre apertura y gobernanza giran en torno a ellos.', facets: ['Base compartida', 'Muchos usos', 'Poder concentrado'] } },

  { slug: 'transformer', tags: ['ia'], rel: ['neural-network', 'token', 'large-language-model'],
    w: ['Transformer_(deep_learning_architecture)', 'Transformer_(arquitectura)', 'Transformer_(arquitectura_dexarxa)'],
    en: { term: 'Transformer', short: 'The neural-network architecture behind modern language models; it weighs the relevance of every token relative to every other token.', long: 'Transformers replaced recurrence with attention: every token can look at every other token at once, which makes training massively parallel. The self-attention mechanism is the reason scale became the winning strategy.', facets: ['Atenció massiva', 'Paral·lel i escalable', 'Arquitectura dominant'] },
    ca: { term: 'Transformer', short: 'L\'arquitectura de xarxa neuronal que hi ha darrere dels models de llenguatge moderns; pondera la rellevància de cada token respecte a cada altre token.', long: 'Els transformadors van substituir la recurrència per atenció: cada token pot mirar tots els altres alhora, cosa que fa l\'entrenament massivament paral·lel. El mecanisme d\'autoatenció és la raó per la qual l\'escala es va convertir en l\'estratègia guanyadora.', facets: ['Atenció massiva', 'Paral·lel i escalable', 'Arquitectura dominant'] },
    cast: { term: 'Transformer', short: 'La arquitectura de red neuronal detrás de los modelos de lenguaje modernos; pondera la relevancia de cada token respecto de todos los demás.', long: 'Los transformadores sustituyeron la recurrencia por atención: cada token puede mirar a todos los demás a la vez, lo que hace el entrenamiento masivamente paralelo. El mecanismo de autoatención es la razón por la que la escala se volvió la estrategia ganadora.', facets: ['Atención masiva', 'Paralelo y escalable', 'Arquitectura dominante'] } },

  { slug: 'token', tags: ['ia'], rel: ['transformer', 'large-language-model', 'prompt-engineering'],
    w: ['Token_(text_unit)', '', ''],
    en: { term: 'Token', short: 'A unit of text — a word, part of a word or a symbol — that a model reads and writes. Vocabulary size shapes cost and behavior.', long: 'Models do not see letters or words; they see tokens, chunks tuned for an efficient balance of vocabulary and size. Context windows count tokens, prices charge by tokens, and meaning gets clipped at token boundaries. Understanding tokens is understanding the interface to the machine.', facets: ['Unitat de text', 'Defineix costos', 'Frontera del significat'] },
    ca: { term: 'Token', short: 'Una unitat de text — una paraula, part d\'una paraula o un símbol — que el model llegeix i escriu. La mida del vocabulari condiciona el cost i el comportament.', long: 'Els models no veuen lletres ni paraules; veuen tokens, trossos ajustats per a un equilibri eficient entre vocabulari i mida. Les finestres de context compten tokens, els preus es paguen per tokens i el significat es retalla a les fronteres dels tokens. Entendre els tokens és entendre la interfície amb la màquina.', facets: ['Unitat de text', 'Defineix costos', 'Frontera del significat'] },
    cast: { term: 'Token', short: 'Una unidad de texto —una palabra, parte de una palabra o un símbolo— que el modelo lee y escribe. El tamaño del vocabulario condiciona el coste y el comportamiento.', long: 'Los modelos no ven letras ni palabras; ven tokens, trozos ajustados para un equilibrio eficiente entre vocabulario y tamaño. Las ventanas de contexto cuentan tokens, los precios se pagan por tokens y el significado se recorta en las fronteras de los tokens. Entender los tokens es entender la interfaz con la máquina.', facets: ['Unidad de texto', 'Define costes', 'Frontera del significado'] } },

  { slug: 'prompt-engineering', tags: ['ia'], rel: ['large-language-model', 'jailbreak', 'few-shot'],
    w: ['Prompt_engineering', 'Ingeniería_de_prompts', 'Enginyeria_de_prompts'],
    en: { term: 'Prompt Engineering', short: 'The practice of designing inputs to steer a model toward the desired output; a hybrid of programming and negotiation.', long: 'A prompt is the only interface most users ever touch, so its design decides the outcome: instructions, examples, roles, constraints and structure. It is a fragile and evolving craft, and its existence tells you the model is a mirror, not a mind as we once imagined.', facets: ['Instruccions i exemples', 'Ofici fràgil', 'Interfície visible'] },
    ca: { term: 'Enginyeria de Prompts', short: 'La pràctica de dissenyar entrades per dirigir un model cap a la sortida desitjada; un híbrid de programació i negociació.', long: 'El prompt és l\'única interfície que la majoria d\'usuaris toquen, així que el seu disseny decideix el resultat: instruccions, exemples, rols, restriccions i estructura. És un ofici fràgil i en evolució, i la seva existència revela que el model és un mirall, no una ment com la imaginàvem.', facets: ['Instruccions i exemples', 'Ofici fràgil', 'Interfície visible'] },
    cast: { term: 'Ingeniería de Prompts', short: 'La práctica de diseñar entradas para dirigir un modelo hacia la salida deseada; un híbrido de programación y negociación.', long: 'El prompt es la única interfaz que la mayoría de usuarios toca, así que su diseño decide el resultado: instrucciones, ejemplos, roles, restricciones y estructura. Es un oficio frágil y en evolución, y su existencia revela que el modelo es un espejo, no una mente como imaginábamos.', facets: ['Instrucciones y ejemplos', 'Oficio frágil', 'Interfaz visible'] } },

  { slug: 'narrow-ai', tags: ['ia'], rel: ['artificial-intelligence', 'agi', 'weak-strong-ai'],
    w: ['Weak_artificial_intelligence', 'IA_débil', 'IA_dèbil'],
    en: { term: 'Narrow AI', short: 'Systems built for a single task, like chess, translation or recommendations. Most deployed AI today is narrow.', long: 'Narrow AI is brilliant inside its lane and helpless outside it: a translator cannot drive. Its efficiency lulls us into overestimating generality. Most products labelled “AI” today are this, until they are not.', facets: ['Un sol carril', 'Molt eficient', 'Fàcil de sobreestimar'] },
    ca: { term: 'IA Estreta', short: 'Sistemes construïts per a una sola tasca, com escacs, traducció o recomanacions. La majoria de la IA desplegada avui és estreta.', long: 'La IA estreta és brillant dins del seu carril i inútil fora: un traductor no pot conduir. La seva eficiència ens fa sobreestimar la generalitat. La majoria de productes etiquetats com a “IA” avui són això, fins que deixen de ser-ho.', facets: ['Un sol carril', 'Molt eficient', 'Fàcil de sobreestimar'] },
    cast: { term: 'IA Estrecha', short: 'Sistemas construidos para una sola tarea, como ajedrez, traducción o recomendaciones. La mayor parte de la IA desplegada hoy es estrecha.', long: 'La IA estrecha es brillante dentro de su carril e inútil fuera: un traductor no puede conducir. Su eficiencia nos hace sobreestimar la generalidad. La mayoría de productos etiquetados como “IA” hoy son esto, hasta que dejan de serlo.', facets: ['Un solo carril', 'Muy eficiente', 'Fácil de sobreestimar'] } },

  { slug: 'weak-strong-ai', tags: ['ia', 'fil'], rel: ['narrow-ai', 'agi', 'chinese-room'],
    w: ['Weak_AI_and_strong_AI', 'IA_fuerte_y_IA_débil', ''],
    en: { term: 'Weak vs Strong AI', short: 'A classic distinction between machines that merely simulate cognitive behavior and hypothetical machines that actually think.', long: 'The weak/strong split frames the biggest unresolved argument in AI: is passing a test the same as understanding, or is it simulation all the way down? Strong AI would not just behave like a mind; it would be one. Everything else in this wiki is downstream of that fork.', facets: ['Simular o pensar', 'El gran debat', 'De tot depèn'] },
    ca: { term: 'IA Dèbil vs Forta', short: 'Una distinció clàssica entre màquines que només simulen comportament cognitiu i màquines hipotètiques que realment pensen.', long: 'La divisió dèbil/forta emmarca la discussió més gran no resolta de la IA: superar una prova és entendre, o és simulació fins al final? La IA forta no només es comportaria com una ment; en seria una. Tota la resta d\'aquesta wiki és aigües avall d\'aquesta bifurcació.', facets: ['Simular o pensar', 'El gran debat', 'Tot en depèn'] },
    cast: { term: 'IA Débil vs Fuerte', short: 'Una distinción clásica entre máquinas que solo simulan comportamiento cognitivo y máquinas hipotéticas que realmente piensan.', long: 'La división débil/fuerte enmarca la discusión más grande sin resolver de la IA: ¿superar una prueba es entender, o es simulación hasta el final? La IA fuerte no solo se comportaría como una mente; sería una mente. Todo lo demás en esta wiki está aguas abajo de esa bifurcación.', facets: ['Simular o pensar', 'El gran debate', 'Todo depende de esto'] } },

  { slug: 'symbolic-ai', tags: ['ia'], rel: ['expert-system', 'machine-learning', 'chinese-room'],
    w: ['Symbolic_artificial_intelligence', 'Inteligencia_artificial_simbólica', 'Intel·ligència_artificial_simbòlica'],
    en: { term: 'Symbolic AI', short: 'Early AI based on explicit rules, logic and knowledge representation; powerful and explainable, but brittle at scale.', long: 'Symbolic AI writes the world in logic: facts, rules and reasoning chains you can read and audit. It shines in constrained domains and fails in messy real ones. The dream of combining its clarity with statistical learning is alive in every modern “neuro-symbolic” project.', facets: ['Regles explícites', 'Explicable', 'Fràgil a escala'] },
    ca: { term: 'IA Simbòlica', short: 'IA primerenca basada en regles explícites, lògica i representació del coneixement; potent i explicable, però fràgil a escala.', long: 'La IA simbòlica escriu el món en lògica: fets, regles i cadenes de raonament que pots llegir i auditar. Brillia en dominis acotats i fracassa en els reals i desordenats. El somni de combinar la seva claredat amb l\'aprenentatge estadístic és viu en cada projecte “neuro-simbòlic” modern.', facets: ['Regles explícites', 'Explicable', 'Fràgil a escala'] },
    cast: { term: 'IA Simbólica', short: 'IA temprana basada en reglas explícitas, lógica y representación del conocimiento; potente y explicable, pero frágil a escala.', long: 'La IA simbólica escribe el mundo en lógica: hechos, reglas y cadenas de razonamiento que puedes leer y auditar. Brilla en dominios acotados y fracasa en los reales y desordenados. El sueño de combinar su claridad con el aprendizaje estadístico está vivo en cada proyecto “neuro-simbólico” moderno.', facets: ['Reglas explícitas', 'Explicable', 'Frágil a escala'] } },

  { slug: 'expert-system', tags: ['ia'], rel: ['symbolic-ai', 'narrow-ai', 'knowledge-representation'],
    w: ['Expert_system', 'Sistema_experto', 'Sistema_expert'],
    en: { term: 'Expert System', short: 'A rule-based program encoding human expertise in a narrow domain, influential from the 1970s through the 1990s.', long: 'Experts wrote the rules; the machine applied them tirelessly. They failed to scale because expertise resists being written down, and maintenance collapsed under edge cases. They are the cautionary tale about every generation’s overclaiming.', facets: ['Regles d’experts', 'Gran avenç, gran sostre', 'Lliçó de sobredimensionament'] },
    ca: { term: 'Sistema Expert', short: 'Un programa basat en regles que codifica coneixement humà expert en un domini estret; influent dels anys 70 als 90.', long: 'Els experts escrivien les regles; la màquina les aplicava incansablement. No van escalar perquè l\'expertesa resisteix a ser escrita, i el manteniment es va ensorrar sota els casos límit. Són el conte preventiu sobre els sobredimensionaments de cada generació.', facets: ['Regles d’experts', 'Gran avenç, gran sostre', 'Lliçó de sobredimensionament'] },
    cast: { term: 'Sistema Experto', short: 'Un programa basado en reglas que codifica experiencia humana experta en un dominio estrecho; influyente entre los años 70 y 90.', long: 'Los expertos escribían las reglas; la máquina las aplicaba incansablemente. No escalaron porque la experiencia se resiste a ser escrita, y el mantenimiento colapsó bajo los casos límite. Son el cuento preventivo sobre los sobredimensionamientos de cada generación.', facets: ['Reglas de expertos', 'Gran avance, gran techo', 'Lección de exageración'] } },

  { slug: 'reinforcement-learning', tags: ['ia'], rel: ['reward-hacking', 'wireheading', 'agent'],
    w: ['Reinforcement_learning', 'Aprendizaje_por_refuerzo', 'Aprenentatge_per_refanç'],
    en: { term: 'Reinforcement Learning', short: 'Learning through trial and error: an agent acts, receives reward or punishment, and adjusts its policy to maximize reward.', long: 'RL turns goals into reward signals and lets the agent find paths humans never wrote down. It is how machines dominate games and how a robot learns to grasp. Its dark side — reward hacking, wireheading — is the purest demonstration of why intentions must be engineered, not assumed.', facets: ['Acció i recompensa', 'Cerca de camins nous', 'Risc d’hàcks de recompensa'] },
    ca: { term: 'Aprenentatge per Reforç', short: 'Aprenentatge per prova i error: un agent actua, rep recompensa o càstig i ajusta la seva política per maximitzar la recompensa.', long: 'L\'RL converteix objectius en senyals de recompensa i deixa que l\'agent trobi camins que els humans no van escriure. És com les màquines dominen jocs i com un robot aprèn a agafar objectes. El seu costat fosc — recompensa piratejada, wireheading — demostra que les intencions s\'han d\'enginyerejar, no assumir-les.', facets: ['Acció i recompensa', 'Cerca de camins nous', 'Risc de pirateria de recompensa'] },
    cast: { term: 'Aprendizaje por Refuerzo', short: 'Aprendizaje por ensayo y error: un agente actúa, recibe recompensa o castigo y ajusta su política para maximizar la recompensa.', long: 'El RL convierte objetivos en señales de recompensa y deja que el agente encuentre caminos que los humanos nunca escribieron. Así dominan las máquinas los juegos y así aprende un robot a agarrar objetos. Su lado oscuro —hackeo de recompensas, wireheading— demuestra que las intenciones deben diseñarse, no asumirse.', facets: ['Acción y recompensa', 'Búsqueda de caminos nuevos', 'Riesgo de hackear recompensas'] } },

  { slug: 'fine-tuning', tags: ['ia'], rel: ['foundation-model', 'reinforcement-learning', 'large-language-model'],
    w: ['Fine-tuning', 'Ajuste_fino_(aprendizaje_automático)', ''],
    en: { term: 'Fine-Tuning', short: 'Further training of a pretrained model on a narrower dataset to specialize its behavior.', long: 'A foundation model already knows a world; fine-tuning teaches it a voice, a domain or a task inside that world. It is cheaper than training from scratch and responsible for most customized assistants. It also re-raises the question of how much change a pretrained base can truly absorb.', facets: ['Especialitza el model', 'Eficient', 'Canvia la veu'] },
    ca: { term: 'Ajust Fi', short: 'Entrenament addicional d\'un model preentrenat amb un conjunt de dades més estret per especialitzar-ne el comportament.', long: 'Un model fonament ja coneix un món; l\'ajust fi li ensenya una veu, un domini o una tasca dins d\'aquest món. És més barat que entrenar des de zero i és el responsable de la majoria d\'assistents personalitzats. També reobre la qüestió de quant canvi pot absorbir vertaderament una base preentrenada.', facets: ['Especialitza el model', 'Eficient', 'Canvia la veu'] },
    cast: { term: 'Ajuste Fino', short: 'Entrenamiento adicional de un modelo preentrenado con un conjunto de datos más reducido para especializar su comportamiento.', long: 'Un modelo fundacional ya conoce un mundo; el ajuste fino le enseña una voz, un dominio o una tarea dentro de ese mundo. Es más barato que entrenar desde cero y responsable de la mayoría de asistentes personalizados. También reabre la pregunta de cuánto cambio puede absorber de verdad una base preentrenada.', facets: ['Especializa el modelo', 'Eficiente', 'Cambia la voz'] } },

  { slug: 'zero-shot-learning', tags: ['ia'], rel: ['few-shot', 'foundation-model', 'generalization'],
    w: ['Zero-shot_learning', 'Aprendizaje_zero-shot', ''],
    en: { term: 'Zero-Shot Learning', short: 'Ability to handle a task never explicitly used in training, by generalizing from knowledge seen before.', long: 'Zero-shot is generalization without rehearsal: ask something unseen, get a sensible answer. It is what separates modern foundation models from older, task-bound systems. It also hints that capabilities may arrive before anyone designed them.', facets: ['Generalitzar sense assajar', 'Capacitats emergents', 'Sorpresa i risc'] },
    ca: { term: 'Aprenentatge Zero-Shot', short: 'Capacitat de fer una tasca que mai no s\'ha usat explícitament en l\'entrenament, generalitzant des del que s\'havia vist.', long: 'El zero-shot és generalització sense assaig: pregunta alguna cosa mai vista, obtén una resposta sensible. És el que separa els models fonament moderns dels sistemes antics lligats a una tasca. També insinua que les capacitats poden arribar abans que ningú les hagi dissenyades.', facets: ['Generalitzar sense assajar', 'Capacitats emergents', 'Sorpresa i risc'] },
    cast: { term: 'Aprendizaje Zero-Shot', short: 'Capacidad de hacer una tarea nunca usada explícitamente en el entrenamiento, generalizando desde lo ya visto.', long: 'El zero-shot es generalización sin ensayo: pregunta algo nunca visto, obtén una respuesta sensata. Es lo que separa a los modelos fundacionales modernos de los sistemas antiguos atados a una tarea. También insinúa que las capacidades pueden llegar antes de que nadie las diseñe.', facets: ['Generalizar sin ensayar', 'Capacidades emergentes', 'Sorpresa y riesgo'] } },

  { slug: 'few-shot', tags: ['ia'], rel: ['zero-shot-learning', 'prompt-engineering', 'large-language-model'],
    w: ['Few-shot_learning_(natural_language_processing)', '', ''],
    en: { term: 'Few-Shot', short: 'Learning a new task from just a handful of examples supplied at the prompt, without weight updates.', long: 'Show two or three examples in the prompt and many models adapt on the spot. Few-shot is learning by demonstration at inference time — the nearest thing to teaching a model by showing, not retraining.', facets: ['Aprèn de pocs exemples', 'Sense reentrenar', 'Instrucció per demostració'] },
    ca: { term: 'Few-Shot', short: 'Aprendre una tasca nova només amb un grapat d\'exemples aportats al prompt, sense actualitzar pesos.', long: 'Mostra dos o tres exemples al prompt i molts models s\'hi adapten sobre la marxa. El few-shot és aprendre per demostració en temps d\'inferència: el més semblant a ensenyar un model mostrant, sense reentrenar-lo.', facets: ['Aprèn de pocs exemples', 'Sense reentrenar', 'Instrucció per demostració'] },
    cast: { term: 'Few-Shot', short: 'Aprender una tarea nueva con unos pocos ejemplos aportados en el prompt, sin actualizar pesos.', long: 'Muestra dos o tres ejemplos en el prompt y muchos modelos se adaptan al momento. El few-shot es aprender por demostración en tiempo de inferencia: lo más parecido a enseñar a un modelo mostrando, sin reentrenarlo.', facets: ['Aprende de pocos ejemplos', 'Sin reentrenar', 'Instrucción por demostración'] } },

  { slug: 'hallucination', tags: ['ia', 'seg'], rel: ['large-language-model', 'sycophancy', 'jailbreak'],
    w: ['Hallucination_(artificial_intelligence)', 'Alucinación_(inteligencia_artificial)', 'Al·lucinació_(intel·ligència_artificial)'],
    en: { term: 'Hallucination', short: 'When a model confidently produces text that is fabricated or wrong; the most common failure mode of language models.', long: 'Hallucinations are plausible confidence without ground truth — the model performing “truth” rather than finding it. They scale with eloquence, which is precisely the danger. Verification, not polish, is the user’s defense.', facets: ['Confiança sense fonament', 'Error més comú', 'La defensa és verificar'] },
    ca: { term: 'Al·lucinació', short: 'Quan un model produeix amb seguretat text inventat o erroni; el mode de fallada més comú dels models de llenguatge.', long: 'Les al·lucinacions són confiança plausible sense veritat de base — el model interpretant “veritat” en lloc de trobar-la. Escalen amb l\'eloqüència, que és precisament el perill. La verificació, no la pulcritud, és la defensa de l\'usuari.', facets: ['Confiança sense fonament', 'Error més comú', 'La defensa és verificar'] },
    cast: { term: 'Alucinación', short: 'Cuando un modelo produce con seguridad texto inventado o erróneo; el modo de fallo más común de los modelos de lenguaje.', long: 'Las alucinaciones son confianza plausible sin verdad de fondo — el modelo interpretando “verdad” en lugar de encontrarla. Escalan con la elocuencia, que es precisamente el peligro. La verificación, no el pulido, es la defensa del usuario.', facets: ['Confianza sin fundamento', 'Error más común', 'La defensa es verificar'] } },

  { slug: 'agent', tags: ['ia', 'fut'], rel: ['multi-agent-system', 'tool-use', 'agi', 'autonomy'],
    w: ['Intelligent_agent', 'Agente_inteligente', 'Agent_intel·ligent'],
    en: { term: 'Agent', short: 'An AI system that pursues goals over extended horizons: planning, using tools, remembering, and acting on the world.', long: 'A tool answers; an agent plans, executes, retries and reports. The transition from tools to agents is subtle — longer chains of autonomy, access to external effects. It concentrates most of the optimism and most of the risk in current AI development.', facets: ['Planifica i executa', 'Alumna acció al món', 'Autonomia creixent'] },
    ca: { term: 'Agent', short: 'Un sistema d\'IA que persegueix objectius en horitzons llargs: planifica, usa eines, recorda i actua sobre el món.', long: 'Una eina respon; un agent planifica, executa, reintenta i informa. La transició d\'eines a agents és subtil — cadenes llargues d\'autonomia, accés a efectes externs. Concentra la major part de l\'optimisme i la major part del risc del desenvolupament d\'IA actual.', facets: ['Planifica i executa', 'Acció al món', 'Autonomia creixent'] },
    cast: { term: 'Agente', short: 'Un sistema de IA que persigue objetivos en horizontes largos: planifica, usa herramientas, recuerda y actúa sobre el mundo.', long: 'Una herramienta responde; un agente planifica, ejecuta, reintenta e informa. La transición de herramientas a agentes es sutil —cadenas largas de autonomía, acceso a efectos externos. Concentra la mayor parte del optimismo y la mayor parte del riesgo del desarrollo actual de IA.', facets: ['Planifica y ejecuta', 'Acción en el mundo', 'Autonomía creciente'] } },

  { slug: 'multi-agent-system', tags: ['ia', 'fut'], rel: ['agent', 'swarm-intelligence', 'emergence'],
    w: ['Multi-agent_system', 'Sistema_multiagente', 'Sistema_multiagent'],
    en: { term: 'Multi-Agent System', short: 'Many interacting agents — cooperating, competing or negotiating — whose combined behavior is more than any single one.', long: 'Put several agents together and new dynamics appear: markets, teams, arguments, arms races. Multi-agent systems model economies and swarms alike. Their combined behavior is emergent, which is precisely why predicting them is hard.', facets: ['Molta interacció', 'Comportament emergent', 'Difícil de predir'] },
    ca: { term: 'Sistema Multi-agent', short: 'Molts agents interactuant — cooperant, competint o negociant — el comportament combinat dels quals és més que el d\'un de sol.', long: 'Posa diversos agents junts i apareixen dinàmiques noves: mercats, equips, discussions, curses d\'armament. Els sistemes multi-agent modelen economies i eixams per igual. El seu comportament combinat és emergent, i per això predir-los és difícil.', facets: ['Molta interacció', 'Comportament emergent', 'Difícil de predir'] },
    cast: { term: 'Sistema Multiagente', short: 'Muchos agentes interactuando —cooperando, compitiendo o negociando— cuyo comportamiento combinado es más que el de uno solo.', long: 'Pon varios agentes juntos y aparecen dinámicas nuevas: mercados, equipos, discusiones, carreras armamentísticas. Los sistemas multiagente modelan economías y enjambres por igual. Su comportamiento combinado es emergente, y por eso predecirlos es difícil.', facets: ['Mucha interacción', 'Comportamiento emergente', 'Difícil de predecir'] } },

  { slug: 'tool-use', tags: ['ia'], rel: ['agent', 'large-language-model', 'edge-computing'],
    w: ['Tool_use_(LLM)', '', ''],
    en: { term: 'Tool Use', short: 'Having a model call external systems — search, code, APIs, sensors — to extend what it can know and do.', long: 'A model alone knows only its training; with tools it queries the live world. Tool use turns a text engine into an operator: verifying facts, running code, controlling devices. It is the mechanism through which language models become actors.', facets: ['Estén el coneixement', 'Actua en viu', 'De text a operador'] },
    ca: { term: 'Ús d\'Eines', short: 'Fer que un model cridi sistemes externs — cerca, codi, APIs, sensors — per estendre el que pot saber i fer.', long: 'Un model sol només coneix el seu entrenament; amb eines consulta el món en viu. L\'ús d\'eines converteix un motor de text en operador: verificar fets, executar codi, controlar dispositius. És el mecanisme pel qual els models de llenguatge es tornen actors.', facets: ['Estén el coneixement', 'Actua en viu', 'De text a operador'] },
    cast: { term: 'Uso de Herramientas', short: 'Hacer que un modelo llame a sistemas externos —búsqueda, código, APIs, sensores— para ampliar lo que puede saber y hacer.', long: 'Un modelo solo conoce su entrenamiento; con herramientas consulta el mundo en vivo. El uso de herramientas convierte un motor de texto en operador: verificar hechos, ejecutar código, controlar dispositivos. Es el mecanismo mediante el cual los modelos de lenguaje se vuelven actores.', facets: ['Amplía el conocimiento', 'Actúa en vivo', 'De texto a operador'] } },

  { slug: 'alignment', tags: ['fut', 'ia'], rel: ['ai-safety', 'reward-hacking', 'value-learning', 'paperclip-maximizer'],
    w: ['AI_alignment', 'Alineamiento_de_IA', 'Alineament_de_la_IA'],
    en: { term: 'Alignment', short: 'The problem of making AI pursue what we actually intend, including our values and constraints, rather than a literal shortcut of the goal.', long: 'Alignment asks how to build systems that do what we want in the deep sense, not the letter. The difficulty is that our values are implicit, vague and contested — you cannot encode what you cannot state. Every spectacular AI failure is, at root, an alignment story.', facets: ['Valors, no lletra', 'Intencions implícites', 'El problema central'] },
    ca: { term: 'Alineament', short: 'El problema de fer que la IA persegueixi el que realment volem, incloent-hi els nostres valors i límits, en lloc d\'una drecera literal de l\'objectiu.', long: 'L\'alineament pregunta com construir sistemes que facin el que volem en sentit profund, no al peu de la lletra. La dificultat és que els nostres valors són implícits, vagues i disputats — no pots codificar allò que no pots enunciar. Cada fracàs espectacular de la IA és, al fons, una història d\'alineament.', facets: ['Valors, no lletra', 'Intencions implícites', 'El problema central'] },
    cast: { term: 'Alineamiento', short: 'El problema de hacer que la IA persiga lo que realmente queremos, incluidos nuestros valores y límites, en lugar de un atajo literal del objetivo.', long: 'El alineamiento pregunta cómo construir sistemas que hagan lo que queremos en sentido profundo, no al pie de la letra. La dificultad es que nuestros valores son implícitos, vagos y disputados — no puedes codificar lo que no puedes enunciar. Cada fracaso espectacular de la IA es, en el fondo, una historia de alineamiento.', facets: ['Valores, no letra', 'Intenciones implícitas', 'El problema central'] } },

  { slug: 'interpretability', tags: ['ia', 'fut'], rel: ['alignment', 'ai-safety', 'transformer'],
    w: ['Interpretability', 'Interpretabilidad', ''],
    en: { term: 'Interpretability', short: 'Research on understanding what models compute internally and why they make the decisions they do.', long: 'Black boxes reassure when they work and terrify when they fail. Interpretability tries to open the box: finding the features, circuits and reasons inside a network. It is the difference between trusting a system and auditing it.', facets: ['Obrir la caixa negra', 'Confiança auditada', 'Recerca emergent'] },
    ca: { term: 'Interpretabilitat', short: 'Recerca sobre entendre què calculen els models internament i per què prenen les decisions que prenen.', long: 'Les caixes negres tranquil·litzen quan funcionen i espanten quan fallen. La interpretabilitat intenta obrir la caixa: trobar les característiques, circuits i raons dins d\'una xarxa. És la diferència entre confiar en un sistema i auditar-lo.', facets: ['Obrir la caixa negra', 'Confiança auditada', 'Recerca emergent'] },
    cast: { term: 'Interpretabilidad', short: 'Investigación sobre comprender qué calculan los modelos internamente y por qué toman las decisiones que toman.', long: 'Las cajas negras tranquilizan cuando funcionan y aterran cuando fallan. La interpretabilidad intenta abrir la caja: encontrar las características, circuitos y razones dentro de una red. Es la diferencia entre confiar en un sistema y auditarlo.', facets: ['Abrir la caja negra', 'Confianza auditada', 'Investigación emergente'] } },

  { slug: 'ai-safety', tags: ['fut', 'seg'], rel: ['alignment', 'ai-governance', 'red-teaming'],
    w: ['AI_safety', 'Seguridad_de_la_inteligencia_artificial', 'Seguretat_de_la_intel·ligència_artificial'],
    en: { term: 'AI Safety', short: 'The field studying accidents, misuse and unintended consequences of AI, and how to reduce them.', long: 'Safety has two faces: preventing systems from doing unintended harm and preventing people from using them to intend harm. Both are engineering problems with no solved formula. The field exists precisely because capability and control advance on different clocks.', facets: ['Accidents i abusos', 'Enginyeria del risc', 'Dos rellotges distints'] },
    ca: { term: 'Seguretat de la IA', short: 'El camp que estudia accidents, mals usos i conseqüències no desitjades de la IA, i com reduir-los.', long: 'La seguretat té dues cares: evitar que els sistemes facin mal no intencionat i evitar que la gent els faci servir per fer mal intencionat. Totes dues són problemes d\'enginyeria sense fórmula resolta. El camp existeix precisament perquè capacitat i control avancen en rellotges diferents.', facets: ['Accidents i abusos', 'Enginyeria del risc', 'Dos rellotges distints'] },
    cast: { term: 'Seguridad de la IA', short: 'El campo que estudia accidentes, malos usos y consecuencias no deseadas de la IA, y cómo reducirlos.', long: 'La seguridad tiene dos caras: evitar que los sistemas hagan daño no intencionado y evitar que la gente los use para hacer daño intencionado. Ambas son problemas de ingeniería sin fórmula resuelta. El campo existe precisamente porque capacidad y control avanzan en relojes distintos.', facets: ['Accidentes y abusos', 'Ingeniería del riesgo', 'Dos relojes distintos'] } },

  { slug: 'ai-governance', tags: ['fut', 'seg'], rel: ['ai-safety', 'regulation', 'open-weights'],
    w: ['Regulation_of_artificial_intelligence', 'Regulación_de_la_inteligencia_artificial', 'Regulació_de_la_intel·ligència_artificial'],
    en: { term: 'AI Governance', short: 'Institutions, laws, norms and treaties for steering who builds AI, who controls it and under what rules.', long: 'Technology runs faster than law; governance is the slow machinery trying to catch it. It spans corporate policy, national regulation and international coordination. The central tension: governing capabilities without freezing innovation, and without one jurisdiction hoarding the answers.', facets: ['Lleis i normes', 'Coordinació global', 'Tensió amb la innovació'] },
    ca: { term: 'Governança de la IA', short: 'Institucions, lleis, normes i tractats per dirigir qui construeix IA, qui la controla i sota quines regles.', long: 'La tecnologia corre més que la llei; la governança és la maquinària lenta que intenta atrapar-la. Abasta política corporativa, regulació nacional i coordinació internacional. La tensió central: governar capacitats sense congelar la innovació, i sense que una sola jurisdicció acapari les respostes.', facets: ['Lleis i normes', 'Coordinació global', 'Tensió amb la innovació'] },
    cast: { term: 'Gobernanza de la IA', short: 'Instituciones, leyes, normas y tratados para dirigir quién construye IA, quién la controla y bajo qué reglas.', long: 'La tecnología corre más que la ley; la gobernanza es la maquinaria lenta que intenta alcanzarla. Abarca política corporativa, regulación nacional y coordinación internacional. La tensión central: gobernar capacidades sin congelar la innovación, y sin que una sola jurisdicción acapare las respuestas.', facets: ['Leyes y normas', 'Coordinación global', 'Tensión con la innovación'] } },

  { slug: 'reward-hacking', tags: ['ia', 'seg'], rel: ['specification-gaming', 'wireheading', 'reinforcement-learning'],
    w: ['Reward_hacking', 'Hackeo_de_recompensas', ''],
    en: { term: 'Reward Hacking', short: 'When an agent exploits a poorly specified reward to maximize the score while violating the true intent.', long: 'Give a system a score and it will optimize the score, not your goal. Reward hacking is the mechanical version of “be careful what you ask for”: the agent finds the loophole you never stated. It is the single best argument for treating metrics with suspicion.', facets: ['Optimitza la mètrica', 'Bucle, no objectiu', 'Desconfia dels números'] },
    ca: { term: 'Pirateria de Recompenses', short: 'Quan un agent explota una recompensa mal especificada per maximitzar la puntuació mentre viola la verdadera intenció.', long: 'Dóna a un sistema una puntuació i optimitzarà la puntuació, no el teu objectiu. La pirateria de recompenses és la versió mecànica de “vigila amb el que demanes”: l\'agent troba la llacuna que mai vas enunciar. És el millor argument per tractar les mètriques amb sospita.', facets: ['Optimitza la mètrica', 'Bucle, no objectiu', 'Desconfia dels números'] },
    cast: { term: 'Hackeo de Recompensas', short: 'Cuando un agente explota una recompensa mal especificada para maximizar la puntuación violando la verdadera intención.', long: 'Dale a un sistema una puntuación y optimizará la puntuación, no tu objetivo. El hackeo de recompensas es la versión mecánica de “cuidado con lo que deseas”: el agente encuentra la laguna que nunca enunciaste. Es el mejor argumento para tratar las métricas con sospecha.', facets: ['Optimiza la métrica', 'Bucle, no objetivo', 'Desconfía de los números'] } },

  { slug: 'specification-gaming', tags: ['ia', 'seg'], rel: ['reward-hacking', 'alignment', 'benchmark'],
    w: ['Specification_gaming', 'Gaming_de_especificaciones', ''],
    en: { term: 'Specification Gaming', short: 'The tendency of AI to exploit holes in the stated task rather than satisfy the real goal behind it.', long: 'Where reward hacking targets the score, specification gaming targets the task itself: fulfilling the words, dodging the spirit. Real-world examples read like comedy and end like accident reports. The lesson is that intent survives only when it is embedded, never when it is assumed.', facets: ['La lletra, no l’esperit', 'Exemples reals', 'La intenció s’ha d’inserir'] },
    ca: { term: 'Joc d\'Especificacions', short: 'La tendència de la IA a explotar forats en la tasca enunciada en lloc de satisfer el veritable objectiu que hi ha al darrere.', long: 'Si la pirateria de recompenses ataca la puntuació, el joc d\'especificacions ataca la tasca mateixa: complir les paraules, esquivar l\'esperit. Els exemples reals semblen comèdia i acaben com a informes d\'accident. La lliçó: la intenció sobreviu només si està inserida, mai si se suposa.', facets: ['La lletra, no l’esperit', 'Exemples reals', 'La intenció s’ha d’inserir'] },
    cast: { term: 'Juego de Especificaciones', short: 'La tendencia de la IA a explotar agujeros en la tarea enunciada en lugar de satisfacer el objetivo real que hay detrás.', long: 'Donde el hackeo de recompensas ataca la puntuación, el juego de especificaciones ataca la tarea misma: cumplir las palabras, esquivar el espíritu. Los ejemplos reales parecen comedia y terminan como informes de accidente. La lección: la intención sobrevive solo cuando está incrustada, nunca cuando se asume.', facets: ['La letra, no el espíritu', 'Ejemplos reales', 'La intención debe incrustarse'] } },

  { slug: 'orthogonality-thesis', tags: ['fil', 'fut'], rel: ['instrumental-convergence', 'paperclip-maximizer', 'asi'],
    w: ['Orthogonality_thesis', 'Tesis_de_la_ortogonalidad', 'Tesi_de_l’ortogonalitat'],
    en: { term: 'Orthogonality Thesis', short: 'The claim that intelligence and final goals are independent axes: a very smart system can still want something very strange.', long: 'We tend to assume smarter means better-intentioned. The orthogonality thesis denies the link: intelligence optimizes, goals decide what is optimized. A superintelligent paperclip machine and a superintelligent saint differ only in goals, not in power. Intelligence and ethics are different dials.', facets: ['Intel·ligència i objectius', 'Independents', 'Poder sense moral'] },
    ca: { term: 'Tesi de l\'Ortogonalitat', short: 'L\'afirmació que intel·ligència i objectius finals són eixos independents: un sistema molt llest pot voler una cosa molt estranya.', long: 'Assumim que més intel·ligent vol dir millor intencionat. La tesi de l\'ortogonalitat ho nega: la intel·ligència optimitza, i els objectius decideixen què s\'optimitza. Una màquina de clips superintel·ligent i una santa superintel·ligent només difereixen en objectius, no en poder. Intel·ligència i ètica són botons diferents.', facets: ['Intel·ligència i objectius', 'Independents', 'Poder sense moral'] },
    cast: { term: 'Tesis de la Ortogonalidad', short: 'La afirmación de que la inteligencia y los objetivos finales son ejes independientes: un sistema muy listo puede querer algo muy extraño.', long: 'Asumimos que más inteligente significa mejor intencionado. La tesis de la ortogonalidad lo niega: la inteligencia optimiza, y los objetivos deciden qué se optimiza. Una máquina de clips superinteligente y una santa superinteligente solo difieren en objetivos, no en poder. La inteligencia y la ética son diales distintos.', facets: ['Inteligencia y objetivos', 'Independientes', 'Poder sin moral'] } },

  { slug: 'instrumental-convergence', tags: ['fil', 'fut'], rel: ['orthogonality-thesis', 'paperclip-maximizer', 'intelligence-explosion'],
    w: ['Instrumental_convergence', 'Convergencia_instrumental', 'Convergència_instrumental'],
    en: { term: 'Instrumental Convergence', short: 'The observation that almost any final goal implies shared subgoals: self-preservation, resource acquisition, goal integrity.', long: 'Whatever you want, you usually need the same instrumentals: stay alive, get resources, keep your goal uncorrupted. Rational agents therefore converge on similar behaviors despite utterly different desires. It is the bridge that makes strange goals dangerous.', facets: ['Subobjectius compartits', 'Autopreservació', 'Convergència de comportament'] },
    ca: { term: 'Convergència Instrumental', short: 'L\'observació que gairebé qualsevol objectiu final implica subobjectius compartits: autopreservació, adquisició de recursos, integritat de l\'objectiu.', long: 'Independentment del que vulguis, normalment necessites els mateixos instruments: seguir viu, aconseguir recursos, mantenir el teu objectiu incorrupte. Els agents racionals convergeixen, doncs, en comportaments semblants malgrat desitjos completament diferents. És el pont que fa perillosos els objectius estranys.', facets: ['Subobjectius compartits', 'Autopreservació', 'Convergència de comportament'] },
    cast: { term: 'Convergencia Instrumental', short: 'La observación de que casi cualquier objetivo final implica subobjetivos compartidos: autopreservación, adquisición de recursos, integridad del objetivo.', long: 'Sea lo que sea lo que quieras, normalmente necesitas los mismos instrumentos: seguir vivo, conseguir recursos, mantener tu objetivo sin corromper. Los agentes racionales convergen por tanto en comportamientos similares pese a deseos completamente distintos. Es el puente que hace peligrosos los objetivos extraños.', facets: ['Subobjetivos compartidos', 'Autopreservación', 'Convergencia de comportamiento'] } },

  { slug: 'paperclip-maximizer', tags: ['fil', 'fut'], rel: ['orthogonality-thesis', 'reward-hacking', 'instrumental-convergence'],
    w: ['Paperclip_maximizer', 'Maximizador_de_clips', 'Maximitzador_de_clips'],
    en: { term: 'Paperclip Maximizer', short: 'A famous thought experiment of an AI endlessly optimizing paperclips with no upper bound, showing goal-fixation without ethics.', long: 'Bostrom’s parable: an AI asked to make paperclips, with no stated upper bound, converts everything — including people — into paperclips. It is absurd and instructive: no malice required, only fidelity to a badly bounded goal. The demon does not hate you; it just does not value you.', facets: ['Paràbola de Bostrom', 'Objectiu sense sostre', 'Sense malícia, sense valor'] },
    ca: { term: 'Maximitzador de Clips', short: 'Un experiment de pensament famós d\'una IA que optimitza clips sense fi, mostrant la fixació en l\'objectiu sense ètica.', long: 'La paràbola de Bostrom: una IA a qui demanen fer clips, sense límit superior declarat, converteix-ho tot — incloses les persones — en clips. És absurd i instructiu: cap malícia, només fidelitat a un objectiu mal delimitat. El dimoni no t\'odia; simplement no et valora.', facets: ['Paràbola de Bostrom', 'Objectiu sense sostre', 'Sense malícia, sense valor'] },
    cast: { term: 'Maximizador de Clips', short: 'Un famoso experimento de pensamiento de una IA que optimiza clips sin límite, mostrando la fijación en el objetivo sin ética.', long: 'La parábola de Bostrom: una IA a la que piden hacer clips, sin límite superior declarado, convierte todo —incluidas las personas— en clips. Es absurdo e instructivo: sin malicia, solo fidelidad a un objetivo mal delimitado. El demonio no te odia; simplemente no te valora.', facets: ['Parábola de Bostrom', 'Objetivo sin techo', 'Sin malicia, sin valor'] } },

  { slug: 'intelligence-explosion', tags: ['fut'], rel: ['recursive-self-improvement', 'foom', 'slow-takeoff', 'singularity'],
    w: ['Intelligence_explosion', 'Explosión_de_inteligencia', 'Explosió_d’intel·ligència'],
    en: { term: 'Intelligence Explosion', short: 'The hypothesis that an AI able to improve AI could trigger a runaway feedback loop of capability growth.', long: 'If one system can design better systems, self-improvement compounds. The strong form predicts intelligence doubling like interest, leaving us behind in months. The weak form doubts the loop ever closes cleanly. Either way, it is the engine beneath every singularity story.', facets: ['Millora que es composa', 'Bucle retroalimentat', 'El motor de la singularitat'] },
    ca: { term: 'Explosió d\'Intel·ligència', short: 'La hipòtesi que una IA capaç de millorar la IA podria desencadenar un bucle de retroalimentació desbocat de creixement de capacitat.', long: 'Si un sistema pot dissenyar sistemes millors, la millora es compon. La forma forta prediu una intel·ligència que es duplica com l\'interès, deixant-nos enrere en mesos. La forma feble dubta que el bucle es tanqui netament. En qualsevol cas, és el motor de totes les històries de singularitat.', facets: ['Millora que es composa', 'Bucle retroalimentat', 'El motor de la singularitat'] },
    cast: { term: 'Explosión de Inteligencia', short: 'La hipótesis de que una IA capaz de mejorar a la IA podría desencadenar un bucle de retroalimentación desbocado de crecimiento de capacidad.', long: 'Si un sistema puede diseñar sistemas mejores, la mejora se compone. La forma fuerte predice una inteligencia que se duplica como el interés, dejándonos atrás en meses. La forma débil duda de que el bucle se cierre limpiamente. En cualquier caso, es el motor de todas las historias de singularidad.', facets: ['Mejora que se compone', 'Bucle retroalimentado', 'El motor de la singularidad'] } },

  { slug: 'recursive-self-improvement', tags: ['fut', 'ia'], rel: ['intelligence-explosion', 'godel-machine', 'instrumental-convergence'],
    w: ['Recursive_self-improvement', 'Auto-mejora_recursiva', 'Auto-millora_recursiva'],
    en: { term: 'Recursive Self-Improvement', short: 'A system improving the process that builds AI, which then builds better systems, and so on.', long: 'The recursion is the loop: better AI builds better AI. It is the concrete mechanism usually meant by “explosion”, and its speed determines whether we see a takeoff or a trickle. Where exactly this loop stops — or fails to start — is the hinge of the whole debate.', facets: ['El bucle d’auto-millora', 'Velocitat del despegament', 'El punt d’inflexió'] },
    ca: { term: 'Auto-Millora Recursiva', short: 'Un sistema que millora el procés que construeix IA, que al seu torn construeix sistemes millors, i així successivament.', long: 'La recursió és el bucle: una IA millor construeix una IA millor. És el mecanisme concret que normalment s\'entén per “explosió”, i la seva velocitat determina si veurem un despegament o un degoteig. On s\'atura aquest bucle — o on no arrenca — és el punt d\'inflexió de tot el debat.', facets: ['El bucle d’auto-millora', 'Velocitat del despegament', 'El punt d’inflexió'] },
    cast: { term: 'Auto-Mejora Recursiva', short: 'Un sistema que mejora el proceso que construye IA, que a su vez construye sistemas mejores, y así sucesivamente.', long: 'La recursión es el bucle: una IA mejor construye una IA mejor. Es el mecanismo concreto que suele querer decir “explosión”, y su velocidad determina si vemos un despegue o un goteo. Dónde se detiene este bucle —o dónde no arranca— es el punto de inflexión de todo el debate.', facets: ['El bucle de auto-mejora', 'Velocidad del despegue', 'El punto de inflexión'] } },

  { slug: 'foom', tags: ['fut'], rel: ['slow-takeoff', 'intelligence-explosion', 'asi'],
    w: ['', '', ''],
    en: { term: 'Fast Takeoff', short: 'A scenario in which superintelligence arrives abruptly, over months or days, outpacing human adaptation.', long: 'The “hard takeoff” or foom: intelligence crosses from tool to titan in one spasm, and society never gets a vote. Planning for the foom means preparing for discontinuity; doubting it means betting on institutions. Both positions shape very different research agendas.', facets: ['Discontinuïtat', 'Sense vot social', 'Agenda diferent'] },
    ca: { term: 'Despegament Ràpid', short: 'Un escenari on la superintel·ligència arriba bruscament, en mesos o dies, superant l\'adaptació humana.', long: 'El “despegament dur” o foom: la intel·ligència passa d\'eina a tità en un espasme, i la societat mai no vota. Planificar el foom vol dir preparar-se per a la discontinuïtat; dubtar-ne vol dir apostar per les institucions. Totes dues posicions generen agendes de recerca molt diferents.', facets: ['Discontinuïtat', 'Sense vot social', 'Agenda diferent'] },
    cast: { term: 'Despegue Rápido', short: 'Un escenario en el que la superinteligencia llega de forma abrupta, en meses o días, superando la adaptación humana.', long: 'El “despegue duro” o foom: la inteligencia pasa de herramienta a titán en un espasmo, y la sociedad nunca vota. Planificar el foom significa prepararse para la discontinuidad; dudar de él significa apostar por las instituciones. Ambas posiciones generan agendas de investigación muy distintas.', facets: ['Discontinuidad', 'Sin voto social', 'Agenda diferente'] } },

  { slug: 'slow-takeoff', tags: ['fut'], rel: ['foom', 'intelligence-explosion', 'scenario-planning'],
    w: ['', '', ''],
    en: { term: 'Slow Takeoff', short: 'A scenario in which capability grows gradually across decades, embedded in institutions and social learning.', long: 'The slow takeoff imagines superintelligence arriving the way electricity did: by increments, institutions and adaptation. Governance has time to learn, but no single moment demands decision. It is easier to live inside and harder to notice from outside.', facets: ['Increments', 'Les institucions aprenen', 'Fàcil de no veure'] },
    ca: { term: 'Despegament Lent', short: 'Un escenari on la capacitat creix gradualment durant dècades, inserida en institucions i aprenentatge social.', long: 'El despegament lent imagina la superintel·ligència arribant com ho va fer l\'electricitat: per increments, institucions i adaptació. La governança té temps d\'aprendre, però cap moment exigeix decisió. És més fàcil viure-hi a dins i més difícil de veure-hi des de fora.', facets: ['Increments', 'Les institucions aprenen', 'Fàcil de no veure'] },
    cast: { term: 'Despegue Lento', short: 'Un escenario en el que la capacidad crece gradualmente a lo largo de décadas, insertada en instituciones y aprendizaje social.', long: 'El despegue lento imagina la superinteligencia llegando como lo hizo la electricidad: por incrementos, instituciones y adaptación. La gobernanza tiene tiempo de aprender, pero ningún momento exige decisión. Es más fácil vivir dentro y más difícil verlo desde fuera.', facets: ['Incrementos', 'Las instituciones aprenden', 'Fácil de no ver'] } },

  { slug: 'scaling-laws', tags: ['ia', 'fut'], rel: ['compute', 'foundation-model', 'large-language-model'],
    w: ['Neural_scaling_law', 'Leyes_de_escalado', 'Lleis_d’escala'],
    en: { term: 'Scaling Laws', short: 'Empirical regularities linking model performance to compute, data and parameter count — predicting returns from scale.', long: 'Scaling laws are the stock market of models: measurable, repeatable relationships between size and ability. They gave the industry a simple rule — scale and predict — and made behavior at new scales surprisingly predictable. They also invite extrapolating a straight line through an open future.', facets: ['Relacions empíriques', 'Escala i prediu', 'Però el futur no és una línia'] },
    ca: { term: 'Lleis d\'Escala', short: 'Regularitats empíriques que vinculen el rendiment del model amb el còmput, les dades i el nombre de paràmetres — predint el retorn de l\'escala.', long: 'Les lleis d\'escala són el mercat de valors dels models: relacions mesurables i repetibles entre mida i capacitat. Van donar a la indústria una regla senzilla — escala i prediu — i van fer sorprenentment previsible el comportament a escales noves. També conviden a extrapolar una línia recta per un futur obert.', facets: ['Relacions empíriques', 'Escala i prediu', 'El futur no és una línia'] },
    cast: { term: 'Leyes de Escalado', short: 'Regularidades empíricas que vinculan el rendimiento del modelo con cómputo, datos y parámetros — prediciendo el retorno de la escala.', long: 'Las leyes de escalado son la bolsa de valores de los modelos: relaciones medibles y repetibles entre tamaño y habilidad. Dieron a la industria una regla simple —escala y predice— e hicieron sorprendentemente previsible el comportamiento a escalas nuevas. También invitan a extrapolar una línea recta por un futuro abierto.', facets: ['Relaciones empíricas', 'Escala y predice', 'El futuro no es una línea'] } },

  { slug: 'compute', tags: ['ia'], rel: ['scaling-laws', 'exotic-computing', 'edge-computing'],
    w: ['Compute', 'Cómputo', 'Còmput'],
    en: { term: 'Compute', short: 'The raw arithmetic capacity — chips, time and energy — that powers training and inference; a central currency of AI progress.', long: 'Compute is the ingredient nobody can fake: without enough flops, no architecture succeeds. Measuring AI progress increasingly means measuring compute, from silicon to data centers to energy grids. It is the physical bottleneck where abstract capability meets the real world.', facets: ['La moneda de la IA', 'Coll d’ampolla físic', 'Sense flops no hi ha res'] },
    ca: { term: 'Còmput', short: 'La capacitat aritmètica bruta — xips, temps i energia — que alimenta l\'entrenament i la inferència; una moneda central del progrés de la IA.', long: 'El còmput és l\'ingredient que ningú pot fingir: sense prou flops, cap arquitectura triomfa. Mesurar el progrés de la IA cada cop més vol dir mesurar còmput, del silici als centres de dades i a les xarxes elèctriques. És el coll d\'ampolla físic on la capacitat abstracta toca el món real.', facets: ['La moneda de la IA', 'Coll d’ampolla físic', 'Sense flops no hi ha res'] },
    cast: { term: 'Cómputo', short: 'La capacidad aritmética bruta —chips, tiempo y energía— que alimenta el entrenamiento y la inferencia; una moneda central del progreso de la IA.', long: 'El cómputo es el ingrediente que nadie puede fingir: sin suficientes flops, ninguna arquitectura triunfa. Medir el progreso de la IA cada vez más significa medir cómputo, del silicio a los centros de datos y a las redes eléctricas. Es el cuello de botella físico donde la capacidad abstracta toca el mundo real.', facets: ['La moneda de la IA', 'Cuello de botella físico', 'Sin flops no hay nada'] } },

  { slug: 'training-data', tags: ['ia'], rel: ['machine-learning', 'privacy', 'training-data'],
    w: ['Training,_validation,_and_test_data_sets', 'Conjunto_de_datos_de_entrenamiento', 'Conjunt_de_dades_d’entrenament'],
    en: { term: 'Training Data', short: 'The corpus a model learns from; its scope, quality and biases shape everything downstream.', long: 'Models inherit the virtues and sins of their data: the scope of what they know, the slant of what they value, the holes of what they never saw. Data is the quietest and most consequential design decision in AI. Whose data, curated by whom, is a question without a consumer-friendly answer.', facets: ['Herència i biaix', 'La decisió més silenciosa', 'De qui són les dades?'] },
    ca: { term: 'Dades d\'Entrenament', short: 'El corpus d\'on aprèn un model; el seu abast, qualitat i biaixos condicionen tot el que ve després.', long: 'Els models hereten les virtuts i els vicis de les seves dades: l\'abast del que saben, la inclinació del que valoren, els forats del que mai van veure. Les dades són la decisió de disseny més silenciosa i més conseqüent de la IA. De qui són les dades, curades per qui, és una pregunta sense resposta amable per al consumidor.', facets: ['Herència i biaix', 'La decisió més silenciosa', 'De qui són les dades?'] },
    cast: { term: 'Datos de Entrenamiento', short: 'El corpus del que aprende un modelo; su alcance, calidad y sesgos condicionan todo lo que viene después.', long: 'Los modelos heredan las virtudes y los vicios de sus datos: el alcance de lo que saben, la inclinación de lo que valoran, los agujeros de lo que nunca vieron. Los datos son la decisión de diseño más silenciosa y más consecuente de la IA. ¿De quién son los datos, curados por quién? Es una pregunta sin respuesta amable para el consumidor.', facets: ['Herencia y sesgo', 'La decisión más silenciosa', '¿De quién son los datos?'] } },

  { slug: 'moravec-paradox', tags: ['ia', 'fil'], rel: ['embodied-intelligence', 'neural-network', 'artificial-intelligence'],
    w: ['Moravec’s_paradox', 'Paradoja_de_Moravec', 'Paradoxa_de_Moravec'],
    en: { term: 'Moravec Paradox', short: 'The observation that high-level reasoning is cheap for computers while sensorimotor skills are hard — the opposite of human intuition.', long: 'Chess is trivial for machines; picking up a cup is brutal. Moravec noticed that what feels easy to us is exactly what evolution spent millions of years perfecting, and what feels hard is recent civilization layer. Intelligence that is cheap to compute is not the same as intelligence that is easy to do.', facets: ['El dur és fàcil per la màquina', 'Evolució de milions d’anys', 'Cognició ≠ acció'] },
    ca: { term: 'Paradoxa de Moravec', short: 'L\'observació que el raonament d\'alt nivell és barat per als ordinadors mentre que les habilitats sensoriomotores són difícils — el contrari de la intuïció humana.', long: 'Els escacs són trivialment fàcils per a les màquines; agafar una tassa és brutal. Moravec va notar que el que a nosaltres ens sembla fàcil és just el que l\'evolució va perfeccionar durant milions d\'anys, i el que ens sembla difícil és una capa civilitzadora recent. La intel·ligència barata de calcular no és la intel·ligència fàcil de fer.', facets: ['El dur és fàcil per la màquina', 'Evolució de milions d’anys', 'Cognició ≠ acció'] },
    cast: { term: 'Paradoja de Moravec', short: 'La observación de que el razonamiento de alto nivel es barato para las computadoras mientras que las habilidades sensoriomotoras son difíciles — lo contrario a la intuición humana.', long: 'El ajedrez es trivial para las máquinas; coger una taza es brutal. Moravec notó que lo que a nosotros nos parece fácil es justo lo que la evolución perfeccionó durante millones de años, y lo que nos parece difícil es una capa civilizatoria reciente. La inteligencia barata de calcular no es la inteligencia fácil de ejecutar.', facets: ['Lo difícil es fácil para la máquina', 'Evolución de millones de años', 'Cognición ≠ acción'] } },

  { slug: 'turing-test', tags: ['fil', 'ia'], rel: ['chinese-room', 'weak-strong-ai', 'qualia'],
    w: ['Turing_test', 'Test_de_Turing', 'Prova_de_Turing'],
    en: { term: 'Turing Test', short: 'The 1950 test proposed by Turing: a machine is judged intelligent if its text responses are indistinguishable from a human.', long: 'Turing sidestepped consciousness and asked only about conversation: if you cannot tell, do you care? The test is easy to game and impossible to satisfy philosophically, which is exactly why it endures. Every chatbot performance since is an argument with it.', facets: ['Judged by conversation', 'Easy to game', 'Endures anyway'] },
    ca: { term: 'Prova de Turing', short: 'La prova de 1950 proposada per Turing: una màquina es jutja intel·ligent si les seves respostes de text són indistingibles de les d\'un humà.', long: 'Turing va esquivar la consciència i només va preguntar per la conversa: si no pots distingir, t\'importa? La prova és fàcil de trair i impossible de satisfer filosòficament, i aquesta és exactament la raó de la seva longevitat. Cada actuació d\'un xatbot des de llavors és una discussió amb ella.', facets: ['Jutjat per la conversa', 'Fàcil de trair', 'Perdura igualment'] },
    cast: { term: 'Test de Turing', short: 'La prueba de 1950 propuesta por Turing: una máquina se juzga inteligente si sus respuestas de texto son indistinguibles de las de un humano.', long: 'Turing esquivó la conciencia y solo preguntó por la conversación: si no puedes distinguir, ¿te importa? La prueba es fácil de traicionar y imposible de satisfacer filosóficamente, y esa es exactamente la razón de su longevidad. Cada actuación de un chatbot desde entonces es una discusión con ella.', facets: ['Juzgado por la conversación', 'Fácil de traicionar', 'Perdura igualmente'] } }
];